def transform(grid):
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    noise = next(v for v, _ in counts.most_common() if v != bg)

    marker = [(r, c, grid[r][c])
              for r in range(len(grid))
              for c in range(len(grid[0]))
              if grid[r][c] not in (bg, noise)]
    r0 = min(r for r, c, v in marker)
    r1 = max(r for r, c, v in marker)
    c0 = min(c for r, c, v in marker)
    c1 = max(c for r, c, v in marker)
    cr, cc = (r0 + r1) // 2, (c0 + c1) // 2
    pattern = [(r - cr, c - cc, v) for r, c, v in marker]

    out = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == noise:
                for dr, dc, v in pattern:
                    rr, c2 = r + dr, c + dc
                    if 0 <= rr < len(grid) and 0 <= c2 < len(grid[0]):
                        out[rr][c2] = v
    return out
